-- denovo
SELECT g.chrom, g.pos, g.ref, g.alt, g.gt AS proband_gt, f.gt AS father_gt, m.gt AS mother_gt, v.info_AF AS af FROM genotypes g INNER JOIN genotypes f ON f.ingest_id = g.ingest_id AND f.chrom = g.chrom AND f.pos = g.pos AND f.ref = g.ref AND f.alt = g.alt AND f.sample_id = 'F' INNER JOIN genotypes m ON m.ingest_id = g.ingest_id AND m.chrom = g.chrom AND m.pos = g.pos AND m.ref = g.ref AND m.alt = g.alt AND m.sample_id = 'M' LEFT JOIN variants v ON v.ingest_id = g.ingest_id AND v.chrom = g.chrom AND v.pos = g.pos AND v.ref = g.ref AND v.alt = g.alt WHERE g.ingest_id = 'i1' AND g.sample_id = 'C1' AND g.gt > 0 AND f.gt = 0 AND m.gt = 0 AND (g.gq IS NULL OR g.gq >= 20) AND (g.dp IS NULL OR g.dp >= 10) AND (f.gq IS NULL OR f.gq >= 20) AND (f.dp IS NULL OR f.dp >= 10) AND (m.gq IS NULL OR m.gq >= 20) AND (m.dp IS NULL OR m.dp >= 10) AND (g.gt != 1 OR g.ad_ref IS NULL OR g.ad_alt IS NULL OR (g.ad_ref + g.ad_alt) = 0 OR (g.ad_alt * 1.0 / (g.ad_ref + g.ad_alt)) BETWEEN 0.25 AND 0.75) AND (v.info_AF IS NULL OR v.info_AF <= 0.01 + 1e-07) ORDER BY g.chrom, g.pos

-- recessive
SELECT g.chrom, g.pos, g.ref, g.alt, g.gt AS proband_gt, f.gt AS father_gt, m.gt AS mother_gt, v.info_AF AS af FROM genotypes g INNER JOIN genotypes f ON f.ingest_id = g.ingest_id AND f.chrom = g.chrom AND f.pos = g.pos AND f.ref = g.ref AND f.alt = g.alt AND f.sample_id = 'F' INNER JOIN genotypes m ON m.ingest_id = g.ingest_id AND m.chrom = g.chrom AND m.pos = g.pos AND m.ref = g.ref AND m.alt = g.alt AND m.sample_id = 'M' LEFT JOIN variants v ON v.ingest_id = g.ingest_id AND v.chrom = g.chrom AND v.pos = g.pos AND v.ref = g.ref AND v.alt = g.alt WHERE g.ingest_id = 'i1' AND g.sample_id = 'C1' AND g.gt = 2 AND f.gt = 1 AND m.gt = 1 AND (g.gq IS NULL OR g.gq >= 20) AND (g.dp IS NULL OR g.dp >= 10) AND (f.gq IS NULL OR f.gq >= 20) AND (f.dp IS NULL OR f.dp >= 10) AND (m.gq IS NULL OR m.gq >= 20) AND (m.dp IS NULL OR m.dp >= 10) AND (g.gt != 1 OR g.ad_ref IS NULL OR g.ad_alt IS NULL OR (g.ad_ref + g.ad_alt) = 0 OR (g.ad_alt * 1.0 / (g.ad_ref + g.ad_alt)) BETWEEN 0.25 AND 0.75) AND (v.info_AF IS NULL OR v.info_AF <= 0.01 + 1e-07) ORDER BY g.chrom, g.pos

-- dominant
SELECT g.chrom, g.pos, g.ref, g.alt, g.gt AS proband_gt, f.gt AS father_gt, m.gt AS mother_gt, v.info_AF AS af FROM genotypes g INNER JOIN genotypes f ON f.ingest_id = g.ingest_id AND f.chrom = g.chrom AND f.pos = g.pos AND f.ref = g.ref AND f.alt = g.alt AND f.sample_id = 'F' INNER JOIN genotypes m ON m.ingest_id = g.ingest_id AND m.chrom = g.chrom AND m.pos = g.pos AND m.ref = g.ref AND m.alt = g.alt AND m.sample_id = 'M' LEFT JOIN variants v ON v.ingest_id = g.ingest_id AND v.chrom = g.chrom AND v.pos = g.pos AND v.ref = g.ref AND v.alt = g.alt WHERE g.ingest_id = 'i1' AND g.sample_id = 'C1' AND g.gt = 1 AND ((f.gt > 0 AND m.gt = 0) OR (f.gt = 0 AND m.gt > 0)) AND (g.gq IS NULL OR g.gq >= 20) AND (g.dp IS NULL OR g.dp >= 10) AND (f.gq IS NULL OR f.gq >= 20) AND (f.dp IS NULL OR f.dp >= 10) AND (m.gq IS NULL OR m.gq >= 20) AND (m.dp IS NULL OR m.dp >= 10) AND (g.gt != 1 OR g.ad_ref IS NULL OR g.ad_alt IS NULL OR (g.ad_ref + g.ad_alt) = 0 OR (g.ad_alt * 1.0 / (g.ad_ref + g.ad_alt)) BETWEEN 0.25 AND 0.75) AND (v.info_AF IS NULL OR v.info_AF <= 0.01 + 1e-07) ORDER BY g.chrom, g.pos

-- denovo_count
SELECT count() FROM genotypes g INNER JOIN genotypes f ON f.ingest_id = g.ingest_id AND f.chrom = g.chrom AND f.pos = g.pos AND f.ref = g.ref AND f.alt = g.alt AND f.sample_id = 'F' INNER JOIN genotypes m ON m.ingest_id = g.ingest_id AND m.chrom = g.chrom AND m.pos = g.pos AND m.ref = g.ref AND m.alt = g.alt AND m.sample_id = 'M' LEFT JOIN variants v ON v.ingest_id = g.ingest_id AND v.chrom = g.chrom AND v.pos = g.pos AND v.ref = g.ref AND v.alt = g.alt WHERE g.ingest_id = 'i1' AND g.sample_id = 'C1' AND g.gt > 0 AND f.gt = 0 AND m.gt = 0 AND (g.gq IS NULL OR g.gq >= 20) AND (g.dp IS NULL OR g.dp >= 10) AND (f.gq IS NULL OR f.gq >= 20) AND (f.dp IS NULL OR f.dp >= 10) AND (m.gq IS NULL OR m.gq >= 20) AND (m.dp IS NULL OR m.dp >= 10) AND (g.gt != 1 OR g.ad_ref IS NULL OR g.ad_alt IS NULL OR (g.ad_ref + g.ad_alt) = 0 OR (g.ad_alt * 1.0 / (g.ad_ref + g.ad_alt)) BETWEEN 0.25 AND 0.75) AND (v.info_AF IS NULL OR v.info_AF <= 0.01 + 1e-07)

-- comphet_candidates
SELECT g.chrom, g.pos, g.ref, g.alt, v.info_AF AS af, CASE WHEN f.gt > 0 AND m.gt = 0 THEN 'paternal' WHEN m.gt > 0 AND f.gt = 0 THEN 'maternal' END AS origin FROM genotypes g INNER JOIN genotypes f ON f.ingest_id = g.ingest_id AND f.chrom = g.chrom AND f.pos = g.pos AND f.ref = g.ref AND f.alt = g.alt AND f.sample_id = 'F' INNER JOIN genotypes m ON m.ingest_id = g.ingest_id AND m.chrom = g.chrom AND m.pos = g.pos AND m.ref = g.ref AND m.alt = g.alt AND m.sample_id = 'M' LEFT JOIN variants v ON v.ingest_id = g.ingest_id AND v.chrom = g.chrom AND v.pos = g.pos AND v.ref = g.ref AND v.alt = g.alt WHERE g.ingest_id = 'i1' AND g.sample_id = 'C1' AND g.gt = 1 AND ((f.gt > 0 AND m.gt = 0) OR (f.gt = 0 AND m.gt > 0)) AND (g.gq IS NULL OR g.gq >= 20) AND (g.dp IS NULL OR g.dp >= 10) AND (f.gq IS NULL OR f.gq >= 20) AND (f.dp IS NULL OR f.dp >= 10) AND (m.gq IS NULL OR m.gq >= 20) AND (m.dp IS NULL OR m.dp >= 10) AND (g.gt != 1 OR g.ad_ref IS NULL OR g.ad_alt IS NULL OR (g.ad_ref + g.ad_alt) = 0 OR (g.ad_alt * 1.0 / (g.ad_ref + g.ad_alt)) BETWEEN 0.25 AND 0.75) AND (v.info_AF IS NULL OR v.info_AF <= 0.01 + 1e-07) ORDER BY g.chrom, g.pos

